python3 << 'EOF'
import json

with open('/app/resources/treasury_bulletin_1992_03.json', 'r') as f:
    data = json.load(f)

# Search for any highway trust fund data in the JSON
def search_dict(d, target_keys=None):
    if target_keys is None:
        target_keys = ['highway', 'trust', 'receipts', 'outlays']

    results = []
    if isinstance(d, dict):
        for key, value in d.items():
            if any(t in str(key).lower() for t in target_keys):
                results.append((key, value))
            if isinstance(value, (dict, list)):
                results.extend(search_dict(value, target_keys))
    elif isinstance(d, list):
        for item in d:
            results.extend(search_dict(item, target_keys))

    return results

results = search_dict(data)
for r in results[:50]:
    print(r)
EOF
